const UnminifiedJavascriptAudit = require('../../../audits/byte-efficiency/unminified-javascript.js');
const assert = require('assert');

const resourceType = 'Script';
describe('Page uses optimized responses', () => {
  it('fails when given unminified scripts with copyright notice', () => {
    const auditResult = UnminifiedJavascriptAudit.audit_({
      Scripts: {
        '123.1':
          `
            /*! Copyright Notice */
            var foo = new Set();
            foo.add(1);
            foo.add(2);

            if (foo.has(2)) {
              console.log('hello!')
            }
          `,
      },
    }, [
      {requestId: '123.1', url: 'foo.js', transferSize: 20 * 1024, resourceType},
    ]);

    assert.ok(auditResult.warnings.length);
    assert.equal(auditResult.items.length, 1);
    assert.equal(auditResult.items[0].url, 'foo.js');
    assert.equal(Math.round(auditResult.items[0].wastedPercent), 57);
    assert.equal(Math.round(auditResult.items[0].wastedBytes / 1024), 11);
  });
});
